defmodule FieldTitle do
  @moduledoc """
  Defines how Vega-Lite generates title for fields.  There are three possible styles:
  
  - `"verbal"` (Default) - displays function in a verbal style (e.g., "Sum of field",
  "Year-month of date", "field (binned)").
  - `"function"` - displays function using parentheses and capitalized texts (e.g.,
  "SUM(field)", "YEARMONTH(date)", "BIN(field)").
  - `"plain"` - displays only the field name without functions (e.g., "field", "date",
  "field").
  """
  @valid_enum_members [
    :verbal,
    :functional,
    :plain,
  ]

  def valid_atom?(value), do: value in @valid_enum_members

  def valid_atom_string?(value) do
    try do
        atom = String.to_existing_atom(value)
        atom in @valid_enum_members
    rescue
        ArgumentError -> false
    end
  end

  def encode(value) do
    if valid_atom?(value) do
        Atom.to_string(value)
    else
        {:error, "Unexpected value when encoding atom: #{inspect(value)}"}
    end
  end

  def decode(value) do
    if valid_atom_string?(value) do
        String.to_existing_atom(value)
    else
        {:error, "Unexpected value when decoding atom: #{inspect(value)}"}
    end
  end

  def from_json(json) do
    json
    |> Jason.decode!()
    |> decode()
  end

  def to_json(data) do
    data
    |> encode()
    |> Jason.encode!()
  end
end

defmodule InvalidValues do
  @moduledoc """
  Defines how Vega-Lite should handle invalid values (`null` and `NaN`).
  - If set to `"filter"` (default), all data items with null values are filtered.
  - If `null`, all data items are included. In this case, invalid values will be
  interpreted as zeroes.
