defmodule VGProjectionType do
  @moduledoc """
  The cartographic projection to use. This value is case-insensitive, for example
  `"albers"` and `"Albers"` indicate the same projection type. You can find all valid
  projection types [in the
  documentation](https://vega.github.io/vega-lite/docs/projection.html#projection-types).
  
  __Default value:__ `mercator`
  """
  @valid_enum_members [
    :albers,
    :albersUsa,
    :azimuthalEqualArea,
    :azimuthalEquidistant,
    :conicConformal,
    :conicEqualArea,
    :conicEquidistant,
    :equirectangular,
    :gnomonic,
    :mercator,
    :orthographic,
    :stereographic,
    :transverseMercator,
  ]

  def valid_atom?(value), do: value in @valid_enum_members

  def valid_atom_string?(value) do
    try do
        atom = String.to_existing_atom(value)
        atom in @valid_enum_members
    rescue
        ArgumentError -> false
    end
  end

  def encode(value) do
    if valid_atom?(value) do
        Atom.to_string(value)
    else
        {:error, "Unexpected value when encoding atom: #{inspect(value)}"}
    end
  end

  def decode(value) do
    if valid_atom_string?(value) do
        String.to_existing_atom(value)
    else
        {:error, "Unexpected value when decoding atom: #{inspect(value)}"}
    end
  end

  def from_json(json) do
    json
    |> Jason.decode!()
    |> decode()
  end

  def to_json(data) do
    data
    |> encode()
    |> Jason.encode!()
  end
end

