defmodule SelectionResolution do
  @moduledoc """
  With layered and multi-view displays, a strategy that determines how
  selections' data queries are resolved when applied in a filter transform,
  conditional encoding rule, or scale domain.
  """
  @valid_enum_members [
    :global,
    :union,
    :intersect,
  ]

  def valid_atom?(value), do: value in @valid_enum_members

  def valid_atom_string?(value) do
    try do
        atom = String.to_existing_atom(value)
        atom in @valid_enum_members
    rescue
        ArgumentError -> false
    end
  end

  def encode(value) do
    if valid_atom?(value) do
        Atom.to_string(value)
    else
        {:error, "Unexpected value when encoding atom: #{inspect(value)}"}
    end
  end

  def decode(value) do
    if valid_atom_string?(value) do
        String.to_existing_atom(value)
    else
        {:error, "Unexpected value when decoding atom: #{inspect(value)}"}
    end
  end

  def from_json(json) do
    json
    |> Jason.decode!()
    |> decode()
  end

  def to_json(data) do
    data
    |> encode()
    |> Jason.encode!()
  end
end

defmodule IntervalSelectionConfig do
  @moduledoc """
  The default definition for an [`interval`](selection.html#type) selection. All properties
  and transformations
  for an interval selection definition (except `type`) may be specified here.
  
  For instance, setting `interval` to `{"translate": false}` disables the ability to move
  interval selections by default.
  - `:bind` - Establishes a two-way binding between the interval selection and the scalesused within the same view. This allows a user to interactively pan andzoom the view.
  - `:empty` - By default, all data values are considered to lie within an empty selection.When set to `none`, empty selections contain no data values.
