  - `:resolve` - With layered and multi-view displays, a strategy that determines howselections' data queries are resolved when applied in a filter transform,conditional encoding rule, or scale domain.
  - `:translate` - When truthy, allows a user to interactively move an interval selectionback-and-forth. Can be `true`, `false` (to disable panning), or a[Vega event stream definition](https://vega.github.io/vega/docs/event-streams/)which must include a start and end event to trigger continuous panning.__Default value:__ `true`, which corresponds to`[mousedown, window:mouseup] > window:mousemove!` which corresponds toclicks and dragging within an interval selection to reposition it.
  - `:zoom` - When truthy, allows a user to interactively resize an interval selection.Can be `true`, `false` (to disable zooming), or a [Vega event streamdefinition](https://vega.github.io/vega/docs/event-streams/). Currently,only `wheel` events are supported.__Default value:__ `true`, which corresponds to `wheel!`.
  """

  defstruct [:bind, :empty, :encodings, :fields, :mark, :on, :resolve, :translate, :zoom]

  @type t :: %__MODULE__{
          bind: BindEnum.t() | nil,
          empty: Empty.t() | nil,
          encodings: [SingleDefChannel.t()] | nil,
          fields: [String.t()] | nil,
          mark: BrushConfig.t() | nil,
          on: any() | nil,
          resolve: SelectionResolution.t() | nil,
          translate: boolean() | String.t() | nil,
          zoom: boolean() | String.t() | nil
        }

  def from_map(m) do
    %IntervalSelectionConfig{
      bind: m["bind"] && BindEnum.decode(m["bind"]),
      empty: m["empty"] && Empty.decode(m["empty"]),
      encodings: m["encodings"] && Enum.map(m["encodings"], &SingleDefChannel.decode/1),
      fields: m["fields"],
      mark: m["mark"] && BrushConfig.from_map(m["mark"]),
      on: m["on"],
      resolve: m["resolve"] && SelectionResolution.decode(m["resolve"]),
      translate: m["translate"],
      zoom: m["zoom"],
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "bind" => struct.bind && BindEnum.encode(struct.bind),
      "empty" => struct.empty && Empty.encode(struct.empty),
      "encodings" => struct.encodings && Enum.map(struct.encodings, &SingleDefChannel.encode/1),
      "fields" => struct.fields,
      "mark" => struct.mark && BrushConfig.to_map(struct.mark),
      "on" => struct.on,
      "resolve" => struct.resolve && SelectionResolution.encode(struct.resolve),
      "translate" => struct.translate,
      "zoom" => struct.zoom,
    }
  end

  def to_json(struct) do
