  def to_map(struct) do
    %{
      "align" => struct.align && HorizontalAlign.encode(struct.align),
      "angle" => struct.angle,
      "baseline" => struct.baseline && VerticalAlign.encode(struct.baseline),
      "cursor" => struct.cursor && Cursor.encode(struct.cursor),
