defmodule Anchor do
  @moduledoc """
  The anchor position for placing the title. One of `"start"`, `"middle"`, or `"end"`. For
  example, with an orientation of top these anchor positions map to a left-, center-, or
  right-aligned title.
  
  __Default value:__ `"middle"` for [single](spec.html) and [layered](layer.html) views.
  `"start"` for other composite views.
  
  __Note:__ [For now](https://github.com/vega/vega-lite/issues/2875), `anchor` is only
  customizable only for [single](spec.html) and [layered](layer.html) views.  For other
  composite views, `anchor` is always `"start"`.
  """
  @valid_enum_members [
    :start,
    :middle,
    :end,
  ]

  def valid_atom?(value), do: value in @valid_enum_members

  def valid_atom_string?(value) do
    try do
        atom = String.to_existing_atom(value)
        atom in @valid_enum_members
    rescue
        ArgumentError -> false
    end
  end

  def encode(value) do
    if valid_atom?(value) do
        Atom.to_string(value)
    else
        {:error, "Unexpected value when encoding atom: #{inspect(value)}"}
    end
  end

  def decode(value) do
    if valid_atom_string?(value) do
        String.to_existing_atom(value)
    else
        {:error, "Unexpected value when decoding atom: #{inspect(value)}"}
    end
  end

  def from_json(json) do
    json
    |> Jason.decode!()
    |> decode()
  end

  def to_json(data) do
    data
    |> encode()
    |> Jason.encode!()
  end
end

