          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "area" => struct.area && MarkConfig.to_map(struct.area),
      "autosize" => encode_autosize(struct.autosize),
      "axis" => struct.axis && AxisConfig.to_map(struct.axis),
