      "line" => struct.line && MarkConfig.to_map(struct.line),
      "mark" => struct.mark && MarkConfig.to_map(struct.mark),
      "numberFormat" => struct.number_format,
      "padding" => encode_padding(struct.padding),
      "point" => struct.point && MarkConfig.to_map(struct.point),
      "projection" => struct.projection && ProjectionConfig.to_map(struct.projection),
      "range" => struct.range
      |> Map.new(fn {key, value} -> {key, encode_range_value(value)} end),
      "rect" => struct.rect && MarkConfig.to_map(struct.rect),
      "rule" => struct.rule && MarkConfig.to_map(struct.rule),
      "scale" => struct.scale && ScaleConfig.to_map(struct.scale),
