defmodule DataFormat do
  @moduledoc """
  An object that specifies the format for parsing the data file.
  
  An object that specifies the format for parsing the data values.
  
  An object that specifies the format for parsing the data.
  - `:parse` - If set to auto (the default), perform automatic type inference to determine the desireddata types.Alternatively, a parsing directive object can be provided for explicit data types. Eachproperty of the object corresponds to a field name, and the value to the desired datatype (one of `"number"`, `"boolean"` or `"date"`).For example, `"parse": {"modified_on": "date"}` parses the `modified_on` field in eachinput record a Date value.For `"date"`, we parse data based using Javascript's[`Date.parse()`](https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Date/parse).For Specific date formats can be provided (e.g., `{foo: 'date:"%m%d%Y"'}`), using the[d3-time-format syntax](https://github.com/d3/d3-time-format#locale_format). UTC dateformat parsing is supported similarly (e.g., `{foo: 'utc:"%m%d%Y"'}`). See more about[UTC time](timeunit.html#utc)
  - `:type` - Type of input data: `"json"`, `"csv"`, `"tsv"`.The default format type is determined by the extension of the file URL.If no extension is detected, `"json"` will be used by default.
  - `:property` - The JSON property containing the desired data.This parameter can be used when the loaded JSON file may have surrounding structure ormeta-data.For example `"property": "values.features"` is equivalent to retrieving`json.values.features`from the loaded JSON object.
  - `:feature` - The name of the TopoJSON object set to convert to a GeoJSON feature collection.For example, in a map of the world, there may be an object set named `"countries"`.Using the feature property, we can extract this set and generate a GeoJSON feature objectfor each country.
  - `:mesh` - The name of the TopoJSON object set to convert to mesh.Similar to the `feature` option, `mesh` extracts a named TopoJSON object set.Unlike the `feature` option, the corresponding geo data is returned as a single, unifiedmesh instance, not as individual GeoJSON features.Extracting a mesh is useful for more efficiently drawing borders or other geographicelements that you do not need to associate with specific regions such as individualcountries, states or counties.
  """

  defstruct [:parse, :type, :property, :feature, :mesh]

  @type t :: %__MODULE__{
          parse: ParseEnum.t() | %{String.t() => any()} | nil,
          type: DataFormatType.t() | nil,
          property: String.t() | nil,
          feature: String.t() | nil,
          mesh: String.t() | nil
        }

  def decode_parse(value) when is_binary(value), do: ParseEnum.decode(value)
  def decode_parse(value) when is_map(value), do: value
  def decode_parse(value) when is_nil(value), do: value
  def decode_parse(_), do: {:error, "Unexpected type when decoding DataFormat.parse"}

  def encode_parse(value) when is_atom(value), do: ParseEnum.encode(value)
  def encode_parse(value) when is_map(value), do: value
  def encode_parse(value) when is_nil(value), do: value
  def encode_parse(_), do: {:error, "Unexpected type when encoding DataFormat.parse"}

  def decode_property(value) when is_binary(value), do: value
  def decode_property(_), do: {:error, "Unexpected type when decoding DataFormat.property"}

  def encode_property(value) when is_binary(value), do: value
  def encode_property(_), do: {:error, "Unexpected type when encoding DataFormat.property"}

  def decode_feature(value) when is_binary(value), do: value
  def decode_feature(_), do: {:error, "Unexpected type when decoding DataFormat.feature"}

  def encode_feature(value) when is_binary(value), do: value
  def encode_feature(_), do: {:error, "Unexpected type when encoding DataFormat.feature"}

  def decode_mesh(value) when is_binary(value), do: value
  def decode_mesh(_), do: {:error, "Unexpected type when decoding DataFormat.mesh"}

  def encode_mesh(value) when is_binary(value), do: value
  def encode_mesh(_), do: {:error, "Unexpected type when encoding DataFormat.mesh"}

  def from_map(m) do
    %DataFormat{
      parse: decode_parse(m["parse"]),
      type: m["type"] && DataFormatType.decode(m["type"]),
      property: (if Map.has_key?(m, "property"), do: decode_property(m["property"])),
      feature: (if Map.has_key?(m, "feature"), do: decode_feature(m["feature"])),
      mesh: (if Map.has_key?(m, "mesh"), do: decode_mesh(m["mesh"])),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "parse" => encode_parse(struct.parse),
      "type" => struct.type && DataFormatType.encode(struct.type),
      "property" => struct.property,
      "feature" => struct.feature,
      "mesh" => struct.mesh,
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

defmodule Data do
  @moduledoc """
  An object describing the data source
  
  Secondary data source to lookup in.
  - `:format` - An object that specifies the format for parsing the data file.An object that specifies the format for parsing the data values.An object that specifies the format for parsing the data.
  - `:url` - An URL from which to load the data set. Use the `format.type` propertyto ensure the loaded data is correctly parsed.
