defmodule DateTimeClass do
  @moduledoc """
  Object for defining datetime in Vega-Lite Filter.
  If both month and quarter are provided, month has higher precedence.
  `day` cannot be combined with other date.
  We accept string for month and day names.
  - `:date` - Integer value representing the date from 1-31.
  - `:day` - Value representing the day of a week.  This can be one of: (1) integer value -- `1`represents Monday; (2) case-insensitive day name (e.g., `"Monday"`);  (3)case-insensitive, 3-character short day name (e.g., `"Mon"`).   <br/> **Warning:** ADateTime definition object with `day`** should not be combined with `year`, `quarter`,`month`, or `date`.
  - `:hours` - Integer value representing the hour of a day from 0-23.
  - `:milliseconds` - Integer value representing the millisecond segment of time.
  - `:minutes` - Integer value representing the minute segment of time from 0-59.
  - `:month` - One of: (1) integer value representing the month from `1`-`12`. `1` represents January;(2) case-insensitive month name (e.g., `"January"`);  (3) case-insensitive, 3-charactershort month name (e.g., `"Jan"`).
  - `:quarter` - Integer value representing the quarter of the year (from 1-4).
  - `:seconds` - Integer value representing the second segment (0-59) of a time value
  - `:utc` - A boolean flag indicating if date time is in utc time. If false, the date time is inlocal time
  - `:year` - Integer value representing the year.
  """

  defstruct [:date, :day, :hours, :milliseconds, :minutes, :month, :quarter, :seconds, :utc, :year]

  @type t :: %__MODULE__{
          date: float() | nil,
