defmodule TimeUnit do
  @moduledoc """
  Time unit for the field to be filtered.
  
  time unit for the field to be filtered.
  
  Time unit (e.g., `year`, `yearmonth`, `month`, `hours`) for a temporal field.
  or [a temporal field that gets casted as ordinal](type.html#cast).
  
  __Default value:__ `undefined` (None)
  
  The timeUnit.
  """
  @valid_enum_members [
    :year,
    :quarter,
    :month,
    :day,
    :date,
    :hours,
    :minutes,
    :seconds,
    :milliseconds,
    :utcyear,
    :utcquarter,
    :utcmonth,
    :utcday,
    :utcdate,
    :utchours,
    :utcminutes,
    :utcseconds,
    :utcmilliseconds,
    :yearquarter,
    :yearquartermonth,
    :yearmonth,
    :yearmonthdate,
    :yearmonthdatehours,
    :yearmonthdatehoursminutes,
    :yearmonthdatehoursminutesseconds,
    :quartermonth,
    :monthdate,
    :hoursminutes,
    :hoursminutesseconds,
    :minutesseconds,
    :secondsmilliseconds,
    :utcyearquarter,
    :utcyearquartermonth,
    :utcyearmonth,
    :utcyearmonthdate,
    :utcyearmonthdatehours,
    :utcyearmonthdatehoursminutes,
    :utcyearmonthdatehoursminutesseconds,
    :utcquartermonth,
    :utcmonthdate,
    :utchoursminutes,
    :utchoursminutesseconds,
    :utcminutesseconds,
    :utcsecondsmilliseconds,
  ]

  def valid_atom?(value), do: value in @valid_enum_members

  def valid_atom_string?(value) do
    try do
        atom = String.to_existing_atom(value)
        atom in @valid_enum_members
    rescue
        ArgumentError -> false
    end
  end

  def encode(value) do
    if valid_atom?(value) do
        Atom.to_string(value)
    else
        {:error, "Unexpected value when encoding atom: #{inspect(value)}"}
    end
  end

  def decode(value) do
    if valid_atom_string?(value) do
        String.to_existing_atom(value)
    else
        {:error, "Unexpected value when decoding atom: #{inspect(value)}"}
    end
  end

  def from_json(json) do
    json
    |> Jason.decode!()
    |> decode()
  end

  def to_json(data) do
    data
    |> encode()
    |> Jason.encode!()
  end
end

