defmodule Projection do
  @moduledoc """
  An object defining properties of geographic projection.
  
  Works with `"geoshape"` marks and `"point"` or `"line"` marks that have a channel (one or
  more of `"X"`, `"X2"`, `"Y"`, `"Y2"`) with type `"latitude"`, or `"longitude"`.
  - `:center` - Sets the projection’s center to the specified center, a two-element array of longitudeand latitude in degrees.__Default value:__ `[0, 0]`
  - `:clip_angle` - Sets the projection’s clipping circle radius to the specified angle in degrees. If`null`, switches to [antimeridian](http://bl.ocks.org/mbostock/3788999) cutting ratherthan small-circle clipping.
  - `:clip_extent` - Sets the projection’s viewport clip extent to the specified bounds in pixels. The extentbounds are specified as an array `[[x0, y0], [x1, y1]]`, where `x0` is the left-side ofthe viewport, `y0` is the top, `x1` is the right and `y1` is the bottom. If `null`, noviewport clipping is performed.
  - `:precision` - Sets the threshold for the projection’s [adaptiveresampling](http://bl.ocks.org/mbostock/3795544) to the specified value in pixels. Thisvalue corresponds to the [Douglas–Peuckerdistance](http://en.wikipedia.org/wiki/Ramer%E2%80%93Douglas%E2%80%93Peucker_algorithm).If precision is not specified, returns the projection’s current resampling precisionwhich defaults to `√0.5 ≅ 0.70710…`.
  - `:rotate` - Sets the projection’s three-axis rotation to the specified angles, which must be a two-or three-element array of numbers [`lambda`, `phi`, `gamma`] specifying the rotationangles in degrees about each spherical axis. (These correspond to yaw, pitch and roll.)__Default value:__ `[0, 0, 0]`
  - `:type` - The cartographic projection to use. This value is case-insensitive, for example`"albers"` and `"Albers"` indicate the same projection type. You can find all validprojection types [in thedocumentation](https://vega.github.io/vega-lite/docs/projection.html#projection-types).__Default value:__ `mercator`
  """

  defstruct [:center, :clip_angle, :clip_extent, :coefficient, :distance, :fraction, :lobes, :parallel, :precision, :radius, :ratio, :rotate, :spacing, :tilt, :type]

  @type t :: %__MODULE__{
          center: [float()] | nil,
          clip_angle: float() | nil,
          clip_extent: [[float()]] | nil,
          coefficient: float() | nil,
          distance: float() | nil,
          fraction: float() | nil,
          lobes: float() | nil,
          parallel: float() | nil,
          precision: %{String.t() => float() | String.t()} | nil,
          radius: float() | nil,
          ratio: float() | nil,
          rotate: [float()] | nil,
          spacing: float() | nil,
          tilt: float() | nil,
          type: VGProjectionType.t() | nil
        }

  def decode_clip_angle(value) when is_float(value), do: value
  def decode_clip_angle(value) when is_integer(value), do: value
  def decode_clip_angle(_), do: {:error, "Unexpected type when decoding Projection.clip_angle"}

