      radius: (if Map.has_key?(m, "radius"), do: decode_radius(m["radius"])),
      ratio: (if Map.has_key?(m, "ratio"), do: decode_ratio(m["ratio"])),
      rotate: m["rotate"],
      spacing: (if Map.has_key?(m, "spacing"), do: decode_spacing(m["spacing"])),
