defmodule SelectionDefType do
  @valid_enum_members [
    :single,
    :multi,
    :interval,
  ]

  def valid_atom?(value), do: value in @valid_enum_members

  def valid_atom_string?(value) do
    try do
        atom = String.to_existing_atom(value)
        atom in @valid_enum_members
    rescue
        ArgumentError -> false
    end
  end

  def encode(value) do
    if valid_atom?(value) do
        Atom.to_string(value)
    else
        {:error, "Unexpected value when encoding atom: #{inspect(value)}"}
    end
  end

  def decode(value) do
    if valid_atom_string?(value) do
        String.to_existing_atom(value)
    else
        {:error, "Unexpected value when decoding atom: #{inspect(value)}"}
    end
  end

  def from_json(json) do
    json
    |> Jason.decode!()
    |> decode()
  end

  def to_json(data) do
    data
    |> encode()
    |> Jason.encode!()
  end
end

defmodule SelectionDef do
  @moduledoc """
  - `:bind` - Establish a two-way binding between a single selection and input elements(also known as dynamic query widgets). A binding takes the form ofVega's [input element binding definition](https://vega.github.io/vega/docs/signals/#bind)or can be a mapping between projected field/encodings and binding definitions.See the [bind transform](bind.html) documentation for more information.Establishes a two-way binding between the interval selection and the scalesused within the same view. This allows a user to interactively pan andzoom the view.
  - `:empty` - By default, all data values are considered to lie within an empty selection.When set to `none`, empty selections contain no data values.
  - `:encodings` - An array of encoding channels. The corresponding data field valuesmust match for a data tuple to fall within the selection.
  - `:fields` - An array of field names whose values must match for a data tuple tofall within the selection.
  - `:nearest` - When true, an invisible voronoi diagram is computed to accelerate discreteselection. The data value _nearest_ the mouse cursor is added to the selection.See the [nearest transform](nearest.html) documentation for more information.
  - `:on` - A [Vega event stream](https://vega.github.io/vega/docs/event-streams/) (object orselector) that triggers the selection.For interval selections, the event stream must specify a [start andend](https://vega.github.io/vega/docs/event-streams/#between-filters).
  - `:resolve` - With layered and multi-view displays, a strategy that determines howselections' data queries are resolved when applied in a filter transform,conditional encoding rule, or scale domain.
  - `:toggle` - Controls whether data values should be toggled or only ever inserted intomulti selections. Can be `true`, `false` (for insertion only), or a[Vega expression](https://vega.github.io/vega/docs/expressions/).__Default value:__ `true`, which corresponds to `event.shiftKey` (i.e.,data values are toggled when a user interacts with the shift-key pressed).See the [toggle transform](toggle.html) documentation for more information.
  - `:mark` - An interval selection also adds a rectangle mark to depict theextents of the interval. The `mark` property can be used to customize theappearance of the mark.
  - `:translate` - When truthy, allows a user to interactively move an interval selectionback-and-forth. Can be `true`, `false` (to disable panning), or a[Vega event stream definition](https://vega.github.io/vega/docs/event-streams/)which must include a start and end event to trigger continuous panning.__Default value:__ `true`, which corresponds to`[mousedown, window:mouseup] > window:mousemove!` which corresponds toclicks and dragging within an interval selection to reposition it.
  - `:zoom` - When truthy, allows a user to interactively resize an interval selection.Can be `true`, `false` (to disable zooming), or a [Vega event streamdefinition](https://vega.github.io/vega/docs/event-streams/). Currently,only `wheel` events are supported.__Default value:__ `true`, which corresponds to `wheel!`.
  """

  @enforce_keys [:type]
  defstruct [:bind, :empty, :encodings, :fields, :nearest, :on, :resolve, :type, :toggle, :mark, :translate, :zoom]

  @type t :: %__MODULE__{
          bind: BindEnum.t() | %{String.t() => VGBinding.t()} | nil,
          empty: Empty.t() | nil,
          encodings: [SingleDefChannel.t()] | nil,
          fields: [String.t()] | nil,
          nearest: boolean() | nil,
          on: any() | nil,
          resolve: SelectionResolution.t() | nil,
          type: SelectionDefType.t(),
          toggle: boolean() | String.t() | nil,
          mark: BrushConfig.t() | nil,
          translate: boolean() | String.t() | nil,
          zoom: boolean() | String.t() | nil
        }

  def decode_bind(value) when is_binary(value), do: BindEnum.decode(value)
  def decode_bind(value) when is_map(value), do: value
  def decode_bind(value) when is_nil(value), do: value
  def decode_bind(_), do: {:error, "Unexpected type when decoding SelectionDef.bind"}

  def encode_bind(value) when is_atom(value), do: BindEnum.encode(value)
  def encode_bind(value) when is_map(value), do: value
  def encode_bind(value) when is_nil(value), do: value
  def encode_bind(_), do: {:error, "Unexpected type when encoding SelectionDef.bind"}

  def from_map(m) do
    %SelectionDef{
      bind: decode_bind(m["bind"]),
      empty: m["empty"] && Empty.decode(m["empty"]),
      encodings: m["encodings"] && Enum.map(m["encodings"], &SingleDefChannel.decode/1),
      fields: m["fields"],
      nearest: m["nearest"],
      on: m["on"],
      resolve: m["resolve"] && SelectionResolution.decode(m["resolve"]),
      type: SelectionDefType.decode(m["type"]),
      toggle: m["toggle"],
      mark: m["mark"] && BrushConfig.from_map(m["mark"]),
      translate: m["translate"],
      zoom: m["zoom"],
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "bind" => encode_bind(struct.bind),
      "empty" => struct.empty && Empty.encode(struct.empty),
      "encodings" => struct.encodings && Enum.map(struct.encodings, &SingleDefChannel.encode/1),
      "fields" => struct.fields,
      "nearest" => struct.nearest,
      "on" => struct.on,
      "resolve" => struct.resolve && SelectionResolution.encode(struct.resolve),
      "type" => SelectionDefType.encode(struct.type),
      "toggle" => struct.toggle,
      "mark" => struct.mark && BrushConfig.to_map(struct.mark),
      "translate" => struct.translate,
      "zoom" => struct.zoom,
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

defmodule TitleParams do
  @moduledoc """
  - `:anchor` - The anchor position for placing the title. One of `"start"`, `"middle"`, or `"end"`. Forexample, with an orientation of top these anchor positions map to a left-, center-, orright-aligned title.__Default value:__ `"middle"` for [single](spec.html) and [layered](layer.html) views.`"start"` for other composite views.__Note:__ [For now](https://github.com/vega/vega-lite/issues/2875), `anchor` is onlycustomizable only for [single](spec.html) and [layered](layer.html) views.  For othercomposite views, `anchor` is always `"start"`.
  - `:offset` - The orthogonal offset in pixels by which to displace the title from its position alongthe edge of the chart.
  - `:orient` - The orientation of the title relative to the chart. One of `"top"` (the default),`"bottom"`, `"left"`, or `"right"`.
  - `:style` - A [mark style property](config.html#style) to apply to the title text mark.__Default value:__ `"group-title"`.
  - `:text` - The title text.
  """

