  def encode_style(value) when is_binary(value), do: value
  def encode_style(value) when is_list(value), do: value
  def encode_style(value) when is_nil(value), do: value
  def encode_style(_), do: {:error, "Unexpected type when encoding TitleParams.style"}

  def decode_text(value) when is_binary(value), do: value
  def decode_text(_), do: {:error, "Unexpected type when decoding TitleParams.text"}

  def encode_text(value) when is_binary(value), do: value
  def encode_text(_), do: {:error, "Unexpected type when encoding TitleParams.text"}

  def from_map(m) do
    %TitleParams{
      anchor: m["anchor"] && Anchor.decode(m["anchor"]),
      offset: (if Map.has_key?(m, "offset"), do: decode_offset(m["offset"])),
      orient: m["orient"] && TitleOrient.decode(m["orient"]),
      style: decode_style(m["style"]),
      text: decode_text(m["text"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "anchor" => struct.anchor && Anchor.encode(struct.anchor),
      "offset" => struct.offset,
      "orient" => struct.orient && TitleOrient.encode(struct.orient),
      "style" => encode_style(struct.style),
      "text" => struct.text,
    }
  end

  def to_json(struct) do
