defmodule Transform do
  @moduledoc """
  - `:filter` - The `filter` property must be one of the predicate definitions:(1) an [expression](types.html#expression) string,where `datum` can be used to refer to the current data object;(2) one of the field predicates: [equal predicate](filter.html#equal-predicate);[range predicate](filter.html#range-predicate), [one-ofpredicate](filter.html#one-of-predicate);(3) a [selection predicate](filter.html#selection-predicate);or (4) a logical operand that combines (1), (2), or (3).
  - `:as` - The field for storing the computed formula value.The field or fields for storing the computed formula value.If `from.fields` is specified, the transform will use the same names for `as`.If `from.fields` is not specified, `as` has to be a string and we put the whole objectinto the data under the specified name.The output fields at which to write the start and end bin values.The output field to write the timeUnit value.
  - `:calculate` - A [expression](types.html#expression) string. Use the variable `datum` to refer to thecurrent data object.
  - `:default` - The default value to use if lookup fails.__Default value:__ `null`
  - `:from` - Secondary data reference.
  - `:lookup` - Key in primary data source.
  - `:bin` - An object indicating bin properties, or simply `true` for using default bin parameters.
  - `:field` - The data field to bin.The data field to apply time unit.
  - `:time_unit` - The timeUnit.
  - `:aggregate` - Array of objects that define fields to aggregate.
  - `:groupby` - The data fields to group by. If not specified, a single group containing all data objectswill be used.
  """

  defstruct [:filter, :as, :calculate, :default, :from, :lookup, :bin, :field, :time_unit, :aggregate, :groupby]

  @type t :: %__MODULE__{
          filter: Predicate.t() | String.t() | nil,
          as: [String.t()] | String.t() | nil,
          calculate: String.t() | nil,
          default: String.t() | nil,
          from: LookupData.t() | nil,
          lookup: String.t() | nil,
          bin: boolean() | BinParams.t() | nil,
          field: String.t() | nil,
          time_unit: TimeUnit.t() | nil,
          aggregate: [AggregatedFieldDef.t()] | nil,
          groupby: [String.t()] | nil
        }

  def decode_filter(%{} = value), do: Predicate.from_map(value)
  def decode_filter(value) when is_binary(value), do: value
  def decode_filter(value) when is_nil(value), do: value
  def decode_filter(_), do: {:error, "Unexpected type when decoding Transform.filter"}

  def encode_filter(%Predicate{} = value), do: Predicate.to_map(value)
